hips-pro',1]],'This email is sent when there is a general message that needs to be communicated to the site administrator.'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Email Footer'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Respectfully,'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'This is the closing message included in every email sent to members and the site administrator through Paid Memberships Pro.'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Email Header'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Dear !!header_name!!,'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'This is the opening message included in every email sent to members and the site administrator through Paid Memberships Pro.'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Your membership at {{ sitename }} has been CANCELLED'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Cancel'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'<p>Your membership at {{ sitename }} has been cancelled.</p>

<p>Account: {{ display_name }} ({{ user_email }})</p>

<p>Membership Level: {{ membership_level_name }}</p>

<p>If you did not request this cancellation and would like more information please contact us at {{ siteemail }}</p>'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'The site administrator can manually cancel a user\'s membership through the WordPress admin or the member can cancel their own membership through your site. This email is sent to the member as confirmation of a cancelled membership.'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Membership for {{ user_login }} at {{ sitename }} has been CANCELLED'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Cancel (admin)'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'<p>The membership for {{ user_login }} at {{ sitename }} has been cancelled.</p>

<p>Account: {{ display_name }} ({{ user_email }})</p>

<p>Membership Level: {{ membership_level_name }}</p>

{% if startdate %}<p>Start Date: {{ startdate }}</p>{% endif %}

{% if enddate %}<p>End Date: {{ enddate }}</p>{% endif %}

