{% if accountnumber %}<p>
	{{ cardtype }}: {{ accountnumber }}<br />
	Expires: {{ expirationmonth }}/{{ expirationyear }}
</p>{% endif %}

<p>Log in to your WordPress admin here: {{ login_url }}</p>'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Members can update the payment method associated with their recurring subscription. This email is sent to the site administrator as a confirmation of a payment method update.'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Membership payment failed at {{ sitename }}'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Payment Failure'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'<p>The current subscription payment for level {{ membership_level_name }} at {{ sitename }} has failed.</p>

<p>
	<strong>Please click the following link to log in and update your billing information to avoid account suspension.</strong><br />
	{{ login_url }}
</p>

<p>Account: {{ display_name }} ({{ user_email }})</p>'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'This email is sent out if a recurring payment has failed, usually due to an expired or cancelled credit card. This email is sent to the member to allowing them time to update payment information without a disruption in access to your site.'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Membership payment failed for {{ display_name }} at {{ sitename }}'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Payment Failure (admin)'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'<p>The subscription payment for {{ user_login }} for level {{ membership_level_name }} at {{ sitename }} has failed.</p>

<p>Account: {{ display_name }} ({{ user_email }})</p>

<p>Membership Level: {{ membership_level_name }}</p>

<p>Log in to your WordPress admin here: {{ login_url }}</p>'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'This email is sent to the site admin when a member\'s payment fails.'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Your payment subscription at {{ sitename }} has been CANCELLED'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Cancelled Auto-Renewals'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'<p>Your payment subscription at {{ sitename }} has been cancelled.</p>

<p>Account: {{ display_name }} ({{ user_email }})</p>

<p>Membership Level: {{ membership_level_name }}</p>

<p>Your access will expire on {{ enddate }}.</p>'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'When a user cancels a membership with a recurring subscription, they will still have access until when their next payment would have been taken. This email is sent to the member to notify them of this change.'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Payment subscription for {{ user_login }} at {{ sitename }} has been CANCELLED'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Cancelled Auto-Renewals (admin)'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'<p>The payment subscription for {{ user_login }} at {{ sitename }} has been cancelled.</p>

