<p>Log in to your WordPress admin here: {{ login_url }}</p>'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'When a user cancels a membership with a recurring subscription, they will still have access until when their next payment would have been taken. This email is sent to the site administrator to notify them of this change.'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'PMPro Page: Account Orders\\4block title'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Dynamic page section that displays a list of the last 5 membership orders for the active member.\\4block description'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'account\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'member\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'order\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'purchases\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'receipt\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'user\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'paid memberships pro\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'pmpro\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'PMPro Page: Account Profile\\4block title'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Dynamic page section that displays the member\'s profile as read-only information with a link to edit fields or change their password.\\4block description'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'fields\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'PMPro Page: Account Links\\4block title'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Dynamic page section that displays custom links available for the active member only. This block is only visible if other Add Ons or custom code have added links.\\4block description'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'access\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'link\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'quick link\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'PMPro Page: Account Memberships\\4block title'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Dynamic page section to display the member\'s active membership information with links to view all membership options, update billing information, and change or cancel membership.\\4block description'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'active\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'PMPro Page: Account (Full)\\4block title'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Dynamic page section to display the selected sections of the Membership Account page including Memberships, Profile, Orders, and Member Links. These sections can also be added via separate blocks.\\4block description'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'billing\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'invoice\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'links\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'profile\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'PMPro Page: Billing\\4block title'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Dynamic page section to display the member\'s billing information. Members can update their subscription payment method from this form.\\4block description'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'credit card\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'payment method\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'PMPro Page: Cancel\\4block title'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Dynamic page section where members can cancel their membership and active subscription if applicable.\\4block description'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'terminate\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Membership Checkout Button\\4block title'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Inserts a button that links directly to membership checkout for the selected level.\\4block description'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'membership\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'checkout\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'button\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'buy\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Membership Checkout Form\\4block title'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Dynamic form that allows users to complete free registration or paid checkout for the selected membership level.\\4block description'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'purchase\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'sell\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'form\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'PMPro Page: Confirmation\\4block title'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Dynamic page section that displays a confirmation message and purchase information for the active member immediately after membership registration and checkout.\\4block description'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'success\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'PMPro Page: Orders\\4block title'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Dynamic page section that displays a list of all orders (purchase history) for the active member. Each order can be selected and viewed in full detail.\\4block description'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'history\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Membership Levels and Pricing Table\\4block title'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Dynamic page section that displays a list of membership levels and pricing, linked to membership checkout. To reorder the display, navigate to Memberships > Settings > Levels.\\4block description'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'level\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'price\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'pricing table\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Login Form\\4block title'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Dynamic form that allows users to log in or recover a lost password. Logged in users can see a welcome message with the selected custom menu.\\4block description'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'log in\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'lost password\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'password reset\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'PMPro Page: Account Profile Edit\\4block title'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Dynamic form that allows the current logged in member to edit their default user profile information and any custom user profile fields.\\4block description'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'custom field\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'user fields\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Content Visibility Block\\4block title'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Nest blocks within this wrapper to show or hide content by membership level, login status, or for non-members.\\4block description'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'block visibility\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'conditional\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'content\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'exclude\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'hide\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'hidden\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'membership excluded\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'membership required\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'private\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'restrict\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'require\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Single Membership Level\\4block title'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Displays a single membership level\'s information and pricing with individual level components.\\4block description'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'membership level\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'pricing\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Level Name\\4block title'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'The name of this membership level.\\4block description'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'name\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Level Expiration\\4block title'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'The expiration text for this membership level.\\4block description'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'expiration\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'text\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Level Description\\4block title'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'The description for this membership level.\\4block description'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'description\\4block keyword'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Level Price\\4block title'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'The price text for this membership level.\\4block description'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Data Collected to Manage Your Membership'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'At checkout, we will collect your name, email address, username, and password. This information is used to setup your account for our site. If you are redirected to an offsite payment gateway to complete your payment, we may store this information in a temporary session variable to setup your account when you return to our site.'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'At checkout, we may also collect your billing address and phone number. This information is used to confirm your credit card. The billing address and phone number are saved by our site to prepopulate the checkout form for future purchases and so we can get in touch with you if needed to discuss your order.'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'At checkout, we may also collect your credit card number, expiration date, and security code. This information is passed to our payment gateway to process your purchase. The last 4 digits of your credit card number and the expiration date are saved by our site to use for reference and to send you an email if your credit card will expire before the next recurring payment.'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'When logged in, we use cookies to track some of your activity on our site including logins, visits, and page views.'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'We maintain logs of transactional emails sent to you for operational and support purposes. These logs include the email content, recipient address, subject line, and delivery status.'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Entries are automatically purged after %s days.'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'If you request deletion of your personal data, all email log entries associated with your account will be permanently removed.'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Display a login form and optional "Logged In" member content.'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Log In - PMPro'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'View'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'My Access'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Preview your membership site by changing the selected view below.'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'View with membership access'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'View with current membership levels'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'View without membership access'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Memberships'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Dashboard'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Members'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Orders'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Subscriptions'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Reports'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Settings'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Add Ons'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'License'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Member'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Edit Member'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Level'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Price'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Action'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Free'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Select the %s membership level'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Select'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'<strong>%s</strong> now'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'<strong>%1$s per %2$s</strong>.'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]],'Year'=>['urls'=>[],'names'=>[],'cmp'=>['paid-memberships-pro',1]]]];
